func:
// 1. Dữ liệu danh sách sinh viên gốc
let danhSach = [
    { name: "Cốp", money: 123 },
    { name: "David", money: 456 },
    { name: "An", money: 789 },
    { name: "Bình", money: 50 }
];

// 2. Thuật toán tự nghĩ: Lọc theo tham số ?min=... trên URL và xếp hạng
let minMoney = Number(msg.req.query.min) || 0;
let ketQua = danhSach.filter(sv => sv.money >= minMoney);

// Sắp xếp giảm dần theo số tiền
ketQua.sort((a, b) => b.money - a.money);

// Gắn thêm xếp loại VIP / Thường
ketQua = ketQua.map(sv => ({
    name: sv.name,
    money: sv.money,
    rank: sv.money >= 400 ? "VIP" : "Thường"
}));

// Tính tổng tiền
let tongTien = ketQua.reduce((sum, sv) => sum + sv.money, 0);

// 3. Đóng gói dữ liệu JSON trả về theo chuẩn đề bài
msg.payload = {
    ok: 1,
    msg: "thành công",
    tong_tien: tongTien,
    dssv: ketQua
};

msg.headers = {
    "Content-Type": "application/json; charset=utf-8"
};

return msg;
